import{legacy2019AutumnNetworkLimits}from'./legacy-2019-autumn-network-review';
import assert from 'node:assert/strict';
import type {Block} from '../../src/core/types';import type {GeneratedBody} from '../../src/core/generators/definition';
import facts from './legacy-2019-autumn-network-facts.json';
const paragraph=(b:Block)=>{assert.equal(b.type,'paragraph');if(b.type!=='paragraph')throw Error('paragraph');return b.text;};
export function legacy2019NetworkLockSchedule(b:string[],exclusiveW=false,skipBlocked=false){
 const seq=[['read W','update X','update Y','update Z'],b],issued=[0,0],done=[new Set<number>(),new Set<number>()],held=new Map('WXYZ'.split('').map(s=>[s,new Set<number>()])),completion:string[]=[],trace:{time:number;transaction:string;event:string;index?:number;item?:string}[]=[];
 for(let time=0;time<8;time++){issued[time%2]++;let progress=true;while(progress){progress=false;for(let tx=0;tx<2;tx++){const pending=Array.from({length:issued[tx]},(_,i)=>i).filter(i=>!done[tx].has(i));for(const i of skipBlocked?pending:pending.slice(0,1)){const item=seq[tx][i].split(' ')[1],owners=held.get(item)!;if((item==='W'&&!exclusiveW)||[...owners].every(o=>o===tx)){owners.add(tx);done[tx].add(i);trace.push({time,transaction:'AB'[tx],event:'grant',index:i,item});progress=true;if(done[tx].size===4){completion.push('AB'[tx]);trace.push({time,transaction:'AB'[tx],event:'unlock'});for(const set of held.values())set.delete(tx);}if(!skipBlocked)break;}}}}}
 const waits:{from:string;to:string;item:string}[]=[];for(let tx=0;tx<2;tx++)if(done[tx].size<4){const next=Array.from({length:4},(_,i)=>i).find(i=>!done[tx].has(i))!,item=seq[tx][next].split(' ')[1];for(const owner of held.get(item)!)if(owner!==tx)waits.push({from:'AB'[tx],to:'AB'[owner],item});}
 const deadlock=waits.some(e=>e.from==='A'&&e.to==='B')&&waits.some(e=>e.from==='B'&&e.to==='A');assert(deadlock||completion.length===2);
 if(!skipBlocked)for(const tx of 'AB'){const es=trace.filter(e=>e.transaction===tx),locks=es.filter(e=>e.event==='grant');assert.deepEqual(locks.map(e=>e.index),Array.from({length:locks.length},(_,i)=>i));let shrinking=false;for(const e of es){if(e.event==='unlock'){assert.equal(locks.length,4);shrinking=true;}else assert(!shrinking);}}
 return{deadlock,completion,waits,trace};
}
const required:Record<number,string[]>={29:['共有ロック','専有ロック','命令の発行時点','後続処理','循環待ち','解放を始めた後'],31:['送信権','環状','時間枠','競合'],32:['ネットワーク層','レイヤ2スイッチにも','物理層','機能分類'],33:['DHCP','NAPT','PPPoE','パケットフィルタリング','指定した要件'],35:['A社WebサーバのFQDN','自社','別のキャッシュ','B社WebサーバのFQDN','名前解決先'],37:['TLS','IPsec','X.509','WPA3','アプリケーション','IP層','証明書','無線LAN'],38:['検証対象','公開鍵','秘密鍵','生成','検証','RSA-PSS','符号化データ','ダイジェストそのもの'],39:['正規認証','ポート','監視','領域','正当な管理用途','必ずダウン']};
const variant:Record<number,string[][]>={31:[['CSMA/CDでは','送信中に衝突を検出','ランダムな待ち時間の後','半二重Ethernet','全二重Ethernet'],['CSMA/CAでは','バックオフ','送信時期をずらし','直接検出','完全になくす保証ではなく']],32:[['宛先MACアドレス','転送先ポート'],['送信元MACアドレス','受信ポート','学習']],33:[['グローバルIPアドレス','ポート番号','識別子を外側'],['LAN側のPC','自動的に割り当てる','DHCPが対応'],['Ethernet上でPPP','セッションを確立','PPPoEが対応'],['送信元や宛先','通過を許可又は禁止','フィルタリングが対応']],35:[['B社のDNSキャッシュ','B社従業員','A社の従業員'],['A社のDNSキャッシュ','A社従業員','B社の従業員']],37:[['WPA3は','PersonalとEnterprise'],['IPsecはIP層','全ての通信が必ず暗号化される','AHは完全性','暗号化の機能とは区別'],['X.509は公開鍵証明書','発行者、主体、公開鍵、有効期間','形式そのもの'],['TLS 1.3は','HTTP専用ではない','レコード層']],38:[['署名者は送信者','受信者が、その送信者の公開鍵','受信者自身の公開鍵や秘密鍵','秘密鍵で署名を作る操作は生成'],['受領通知1通','署名者は元の受信者','検証するのは元の送信者','受信者の公開鍵で通知','別のメッセージ']],39:[['バックドアは','迂回','一般公開','全てを意味するものではない'],['ポートスキャナは','UDP','応答がない','必ず断定できる'],['ミラーポートは','スイッチで受信する方向'],['バッファオーバフロー攻撃は','静的領域','領域外','ダウン']]};
function figure(b:Block,profile:string){assert.equal(b.type,'diagram');if(b.type!=='diagram'||b.scene.kind!=='source_figure')throw Error('figure');assert.equal(b.scene.profile,profile);assert.deepEqual(b.scene.values,[0]);assert(b.alt&&b.alt.length>100);assert(!/循環待ち|デッドロック|正答|DHCP|NAPT|PPPoE|フィルタリング/.test(b.alt));return b;}
export function assertLegacy2019AutumnNetwork(source:string,b:GeneratedBody,values:number[]){
 const n=Number(source.split('-').at(-1)),v=values[0],expected=facts.cases.find(c=>c.source===source&&c.input[0]===v);assert(expected);assert.equal(values.length,1);assert.equal(b.choices.length,4);assert.equal(b.answerParts,undefined);assert.equal(paragraph(b.prompt[0]),expected.stem);assert.equal(b.prompt.length,n===29?4:n===33?2:1);
 let truth:boolean[]=[];
 if(n===29){assert.deepEqual(b.prompt.slice(1,3).map(paragraph),facts.originals.find(o=>o.questionNumber===29)!.notes);const f=figure(b.prompt[3],'legacy-2019-two-phase-locking');for(const s of['read W','update X','update Y','update Z','①','②','③','④','命令発行時点'])assert(f.alt!.includes(s));
  const rows=b.choices.map((bs,i)=>{assert.equal(bs.length,1);assert.equal(bs[0].type,'table');if(bs[0].type!=='table')throw Error('table');assert.deepEqual(bs[0].columns,['①','②','③','④']);assert.equal(bs[0].caption,'データ処理順序');assert.equal(bs[0].rows.length,1);const row=bs[0].rows[0] as string[];assert(row.every(c=>typeof c==='string'));assert.deepEqual(row,expected.choices[i]);return row;});assert.equal(new Set(rows.map(r=>JSON.stringify(r))).size,4);const schedules=rows.map(r=>legacy2019NetworkLockSchedule(r));truth=schedules.map(r=>!r.deadlock);
  for(const row of [0,1,3]){assert(b.explanation.includes(rows[row].join('→')));for(const w of schedules[row].waits)assert(b.explanation.includes(`${w.from}が${w.item}を待`));}
  const correct=schedules[2];assert.deepEqual(correct.completion,v&4?['A','B']:['B','A']);assert(b.explanation.includes(rows[2].join('→')));assert(b.explanation.includes(v&4?'Aが先にXを獲得':'Bが先にXを獲得'));
 }else{
  const ids=expected.choiceFactIds!;const registry=facts.facts.records as Record<string,{text:string;category:string;mechanism:string|Record<string,string>}>;const propositions=b.choices.map((bs,i)=>{assert.equal(bs.length,1);const text=paragraph(bs[0]);assert.equal(text,expected.choices[i]);const f=registry[ids[i]];assert(f);assert.equal(text,f.text);return f;});
  if(n===31)truth=propositions.map(f=>f.category===['CSMA/CD','CSMA/CA'][v]);
  if(n===32){const caps=facts.facts.deviceCapabilities as Record<string,string[]>;truth=propositions.map(f=>caps.L3.includes(f.category)&&['media_converter','repeater_hub','L2'].every(d=>!caps[d].includes(f.category)));}
  if(n===33){figure(b.prompt[1],'legacy-2019-home-network');truth=propositions.map(f=>f.category===['public_address_sharing','configuration_assignment','ppp_over_ethernet','packet_admission'][v]);}
  if(n===35){const cache=v===0?'B':'A',records:{[resolver:string]:{[site:string]:string}}={A:{A:'A-normal',B:'B-normal'},B:{A:'A-normal',B:'B-normal'}};records[cache].A='attacker-X';truth=propositions.map(f=>{const m=f.mechanism as{employee:string;site:string};return records[m.employee][m.site]==='attacker-X';});}
  if(n===37)truth=propositions.map(f=>f.category===['wireless_security','network_packet_security','certificate_format','application_channel_crypto'][v]);
  if(n===38){const owner=v===0?'sender':'receiver',operator=v===0?'receiver':'sender';truth=propositions.map(f=>{const m=f.mechanism as{owner:string;kind:string;operator:string;operation:string};return m.owner===owner&&m.kind==='public'&&m.operator===operator&&m.operation==='verify';});assert(b.prompt.every(p=>p.type!=='paragraph'||!p.text.includes('生成鍵')));if(v===1)for(const s of['受領通知','元の送信者に返送','元のメッセージ送信時の役割'])assert(paragraph(b.prompt[0]).includes(s));}
  if(n===39)truth=propositions.map(f=>f.category===['authentication_bypass','port_discovery_tool','monitoring_copy_port','buffer_boundary_overwrite'][v]);
 }
 assert.equal(truth.filter(Boolean).length,1);assert.equal(b.correctIndex,truth.indexOf(true));assert(b.explanation.length>150);assert(!/原[アイウエ]の|選択肢は順|左から順|生成条件|転載|編集方針/.test(b.explanation));for(const s of required[n])assert(b.explanation.includes(s),`${source} explanation missing ${s}`);for(const s of variant[n]?.[v]??[])assert(b.explanation.includes(s),`${source} explanation condition${v} missing ${s}`);for(const sentence of legacy2019AutumnNetworkLimits(n,v))assert(b.explanation.includes(sentence),`${source} explanation polarity/scope missing ${sentence}`);return truth;
}
